"""Versioned visitor-facing preview using preserved results and team-colour candidates."""
import csv
import json
from pathlib import Path

OUT = Path(__file__).resolve().parent
BASE = OUT.parents[3]
DATA = BASE / 'source-unified-2026-10-06-v01'
def read(name):
    with (DATA / name).open(encoding='utf-8-sig', newline='') as f:
        return list(csv.DictReader(f))
rows = read('completed_matches.csv')
scheduled = read('scheduled_matches.csv')
palette = {
'Brighton':('#0057B8','#FFFFFF'),'Fulham':('#FFFFFF','#111111'),'Wolverhampton Wanderers':('#FDB913','#111111'),'Sheffield United':('#C8102E','#FFFFFF'),'Brentford':('#D71920','#FFFFFF'),'Leeds':('#FFFFFF','#244A9B'),'Nottingham Forest':('#DD0000','#FFFFFF'),'Luton':('#F47B20','#172A53'),'Ipswich':('#0057B8','#FFFFFF'),'Coventry':('#69B3E7','#FFFFFF'),'Aston Villa':('#670E36','#95BFE5'),'Everton':('#003399','#FFFFFF'),'Bournemouth':('#D71920','#111111'),'Southampton':('#D71920','#FFFFFF'),'Leicester':('#003090','#FDBE11'),'Sunderland':('#EB172B','#FFFFFF'),'Crystal Palace':('#1B458F','#C4122E'),'Chelsea':('#034694','#FFFFFF'),'West Ham':('#7A263A','#1BB1E7'),'Tottenham':('#FFFFFF','#132257'),'Arsenal':('#D71920','#FFFFFF'),'Newcastle United':('#111111','#FFFFFF'),'Liverpool':('#C8102E','#FFFFFF'),'Manchester City':('#6CABDD','#FFFFFF'),'Manchester United':('#DA291C','#111111'),'Hull':('#F6A800','#111111'),'Burnley':('#6C1D45','#99D6EA'),
'Malaga':('#54A9DD','#FFFFFF'),'Sevilla':('#FFFFFF','#D71920'),'Deportivo La Coruna':('#0066B3','#FFFFFF'),'Real Sociedad':('#0067B1','#FFFFFF'),'Espanyol':('#007FC8','#FFFFFF'),'Getafe':('#0055A4','#FFFFFF'),'Atletico Madrid':('#CB3524','#FFFFFF'),'Las Palmas':('#F9DC00','#0055A4'),'Rayo Vallecano':('#FFFFFF','#E53027'),'Valencia':('#FFFFFF','#E57200'),'Athletic Club':('#D71920','#FFFFFF'),'Barcelona':('#004D98','#A50044'),'Real Madrid':('#FFFFFF','#B69C4A'),'Levante':('#005CA9','#A6192E'),'Celta Vigo':('#8AC3EE','#FFFFFF'),'Real Betis':('#008547','#FFFFFF'),'Villarreal':('#F5DC00','#0055A4'),'Granada':('#D71920','#FFFFFF'),'Osasuna':('#D71920','#152B49'),'Alaves':('#0055A4','#FFFFFF'),'Leganes':('#0055A4','#FFFFFF'),'Elche':('#FFFFFF','#008547'),'Almeria':('#D71920','#FFFFFF'),'Girona':('#D71920','#FFFFFF'),'Real Valladolid':('#6C248C','#FFFFFF'),'Mallorca':('#D71920','#111111'),'Cadiz':('#F9DC00','#0055A4'),'Real Oviedo':('#0055A4','#FFFFFF'),'Racing Santander':('#FFFFFF','#008547')}
official = {
'Arsenal':'https://www.arsenal.com/media/455139/download',
'Leeds':'https://www.leedsunited.com/en/news/leeds-united-and-adidas-unveil-25-26-home-kit',
'Barcelona':'https://www.fcbarcelona.com/en/club/identity/colours',
'Real Madrid':'https://shop.realmadrid.com/en-gb/product/rmcfmz0899-mens-home-jersey-25-26-white',
'Malaga':'https://www.malagacf.com/en/news/una-blanquiazul-reconocible-y-con-identidad',
'Espanyol':'https://www.rcdespanyol.com/es/noticia/llegan-las-nuevas-camisetas/17346'}
teams = {}
for row in rows + scheduled:
    for side in ('home','away'):
        key, name = row[side+'_team_key'], row[side+'_team_name']
        primary, secondary = palette[name]
        teams[key] = dict(id=key,name=name,league=row['league'],primary=primary,secondary=secondary,
                          colour_family_status='OFFICIAL_FAMILY_CHECKED' if name in official else 'DESIGN_CANDIDATE_UNVERIFIED',
                          source_url=official.get(name),hex_status='UI_SELECTED_NOT_OFFICIAL_HEX')
assert len(teams) == 56
with (OUT/'team-colours.json').open('x', encoding='utf-8') as f:
    json.dump(dict(note='Colour families checked for six teams; other palettes are unverified design candidates. All hexadecimal values selected for this UI, not extracted official brand standards.',teams=list(teams.values())),f,ensure_ascii=False,indent=2)
def match(r, completed):
    return dict(id=r['match_key'],league=r['league'],season=r['season'],date=r['source_date'],home=r['home_team_key'],away=r['away_team_key'],hg=float(r['home_goals']) if completed else None,ag=float(r['away_goals']) if completed else None,hx=float(r['home_xg']) if completed else None,ax=float(r['away_xg']) if completed else None,source=r['source_url'])
payload = dict(teams=teams,completed=[match(r,True) for r in rows],scheduled=[match(r,False) for r in scheduled],last_date=max(r['source_date'] for r in rows))
page = r'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MatchDesk · 경기 분석실</title><style>
*{box-sizing:border-box}body{margin:0;background:#f4f5f7;color:#17283b;font:16px/1.5 system-ui,'Malgun Gothic',sans-serif;font-variant-numeric:tabular-nums}button,select{font:inherit;cursor:pointer}button:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid #2454c6;outline-offset:3px}header{background:#111f32;color:white;padding:18px max(22px,calc((100% - 1150px)/2));display:flex;align-items:center;justify-content:space-between;gap:20px}header strong{font-size:24px;letter-spacing:-1px}header small{font-size:13px;color:#c4cfda;margin-left:12px}nav{display:flex;gap:5px}nav button{border:0;background:none;color:#c4cfda;padding:10px 16px;border-radius:7px;min-height:44px}nav button.active{color:#111f32;background:#d5f36b;font-weight:700}main{max-width:1194px;margin:auto;padding:30px 22px}h1{font-size:28px;margin:0}h2{font-size:20px;margin:0 0 18px}h3{font-size:16px;margin:0}p{margin:8px 0}.muted{color:#536174;font-size:14px}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:24px;flex-wrap:wrap}select{border:1px solid #cbd4df;border-radius:7px;background:white;padding:10px 32px 10px 12px;min-height:44px;max-width:100%}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.fixture{border:1px solid #dce2e9;background:white;border-radius:12px;text-align:left;padding:18px;transition:box-shadow .15s;min-width:0}.fixture:hover{box-shadow:0 4px 18px #111f3214}.fixture.selected{outline:2px solid #17283b}.fixture .pair{display:flex;justify-content:space-between;gap:8px;margin-top:16px}.mini{display:flex;gap:8px;align-items:center;min-width:0;font-size:14px}.chip{width:25px;height:25px;border:1px solid #8897a655;border-radius:50%;display:inline-block;flex-shrink:0;background:linear-gradient(90deg,var(--p) 0 65%,var(--s) 65%)}.panel{border:1px solid #dce2e9;background:white;border-radius:14px;padding:24px;margin-top:22px}.matchhead{display:grid;grid-template-columns:1fr auto 1fr;gap:20px;align-items:center;margin:18px 0 28px}.club{display:flex;align-items:center;gap:14px;font-weight:750;font-size:22px;min-width:0}.club.right{justify-content:flex-end;text-align:right}.crest{width:56px;height:64px;display:grid;place-items:center;border-radius:12px 12px 22px 22px;border:1px solid #8897a655;background:linear-gradient(100deg,var(--p) 0 68%,var(--s) 68%);color:var(--text);font-weight:800;font-size:18px;flex-shrink:0}.versus{font-size:26px;font-weight:700;color:#536174}.grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.stat{display:grid;grid-template-columns:60px 1fr 60px;gap:16px;align-items:center;margin-top:22px}.stat strong{font-size:23px}.stat strong:last-child{text-align:right}.stat label{display:block;text-align:center;color:#536174;font-size:14px;margin-bottom:8px}.bars{display:grid;grid-template-columns:1fr 1fr;gap:5px}.track{height:8px;background:#eef1f5;border-radius:4px;overflow:hidden}.track.left{display:flex;justify-content:flex-end}.fill{height:100%;border-radius:4px;border:1px solid #14293b26}.form{display:flex;gap:6px;margin-top:16px}.form span{border-radius:5px;background:#edf1f5;min-width:30px;height:30px;display:grid;place-items:center;font-size:13px;font-weight:700;color:#314255}.chart{width:100%;height:180px}.legend{display:flex;gap:20px;font-size:13px;color:#536174}.legend i{display:inline-block;width:20px;border-top:3px solid var(--c);margin-right:7px;vertical-align:middle}.legend .dash{border-top-style:dashed}.status{font-size:12px;background:#edf1f5;padding:4px 7px;border-radius:5px;color:#536174}.tablewrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:12px 10px;border-bottom:1px solid #e7ebf0;text-align:right;white-space:nowrap}th:first-child,td:first-child{text-align:left}th{color:#536174;font-weight:500}td a{color:inherit;text-decoration:none}td a:hover{text-decoration:underline}.note{font-size:13px;color:#536174;margin:18px 0}section[hidden]{display:none}footer{border-top:1px solid #dce2e9;margin-top:28px;padding-top:16px;font-size:12px;color:#536174}.teamchooser{display:flex;gap:10px;flex-wrap:wrap}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-top:24px}.summary strong{display:block;font-size:30px}.summary label{font-size:13px;color:#536174}@media(max-width:750px){header{flex-wrap:wrap;padding:18px}header small{display:none}main{padding:22px 14px}.cards{grid-template-columns:1fr}.grid{grid-template-columns:1fr}.panel{padding:18px}.club{font-size:16px;gap:8px}.crest{width:38px;height:44px;font-size:12px}.matchhead{gap:8px}.summary{grid-template-columns:repeat(2,1fr)}.stat{grid-template-columns:48px 1fr 48px;gap:8px}.stat strong{font-size:20px}}
@media(prefers-reduced-motion:reduce){*{transition:none!important}}
</style></head><body><header><div><strong>MatchDesk</strong><small>AI 경기 분석실</small></div><nav aria-label="주 메뉴"><button data-view="matches" class="active">경기</button><button data-view="team">팀</button><button data-view="league">리그</button></nav></header><main><div class="toolbar"><div><h1 id="heading">다가오는 경기</h1><div class="muted">자료 기준 <span id="lastdate"></span></div></div><label>리그 <select id="league"><option value="EPL">프리미어리그</option><option value="La_liga">라리가</option></select></label></div>
<section id="matches"><div class="cards" id="fixtures"></div><article class="panel"><div class="toolbar"><h2 style="margin:0">최근 전력 비교</h2><span class="status">최근 리그 5경기</span></div><div id="comparison"></div></article><div class="grid"><article class="panel"><h2>기대 득점 흐름</h2><div id="trend"></div></article><article class="panel"><h2>최근 경기</h2><div id="recent"></div></article></div></section>
<section id="team" hidden><div class="teamchooser"><label>팀 <select id="teamselect"></select></label><label>시즌 <select id="season"><option>2026/27</option><option>2025/26</option><option>2024/25</option><option>2023/24</option></select></label></div><article class="panel" id="teamcontent"></article></section>
<section id="leagueview" hidden><article class="panel"><h2>2026/27 · 승점순 통계</h2><div class="tablewrap" id="standings"></div></article></section><footer>저장 자료 기반 미리보기 · 경기 날짜는 원본 표기 · 팀 색상은 화면용 대표색</footer></main><script id="data" type="application/json">__PAYLOAD__</script><script>
const D=JSON.parse(document.getElementById('data').textContent),T=D.teams;let L='EPL',V='matches',selected=null;
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function dark(c){let a=c.slice(1).match(/../g).map(x=>parseInt(x,16)/255).map(x=>x<=.04045?x/12.92:((x+.055)/1.055)**2.4);return .2126*a[0]+.7152*a[1]+.0722*a[2]<.36}
function colour(id){const t=T[id];return dark(t.primary)?t.primary:dark(t.secondary)?t.secondary:'#314255'}
function badge(id,big=false){const t=T[id];return `<span class="${big?'crest':'chip'}" style="--p:${t.primary};--s:${t.secondary};--text:${dark(t.primary)?'#fff':'#17283b'}" ${big?'':'aria-hidden="true"'}>${big?esc(t.name.split(' ').map(x=>x[0]).join('').slice(0,3)):''}</span>`}
function team(id){return `<span class="mini">${badge(id)}${esc(T[id].name)}</span>`}
function games(id,season=null,before=null){return D.completed.filter(m=>(m.home===id||m.away===id)&&(!season||m.season===season)&&(!before||m.date<before)).sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id))}
function calc(id,ms){let n=ms.length,p=0,gf=0,ga=0,xg=0,xga=0,w=0,d=0,l=0;ms.forEach(m=>{let h=m.home===id,f=h?m.hg:m.ag,a=h?m.ag:m.hg;p+=f>a?3:f===a?1:0;w+=f>a;d+=f===a;l+=f<a;gf+=f;ga+=a;xg+=h?m.hx:m.ax;xga+=h?m.ax:m.hx});return {n,p,gf,ga,xg,xga,w,d,l}}
function form(id,ms){return `<div class="form" aria-label="최근 경기 결과">${ms.map(m=>{let f=m.home===id?m.hg:m.ag,a=m.home===id?m.ag:m.hg;return `<span title="${m.date}">${f>a?'승':f===a?'무':'패'}</span>`}).join('')}</div>`}
function rows(id,ms){return `<div class="tablewrap"><table><thead><tr><th>상대</th><th>결과</th><th>xG</th></tr></thead><tbody>${ms.slice().reverse().map(m=>{let h=m.home===id;return `<tr><td><a href="${m.source}" target="_blank" rel="noopener">${esc(T[h?m.away:m.home].name)}<br><small class="muted">${m.date}</small></a></td><td>${h?m.hg:m.ag} : ${h?m.ag:m.hg}</td><td>${(h?m.hx:m.ax).toFixed(2)}</td></tr>`}).join('')}</tbody></table></div>`}
function renderMatches(){let fs=D.scheduled.filter(m=>m.league===L&&m.date>='2026-10-06').sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id)).slice(0,3);if(!fs.length){$('fixtures').textContent='예정 경기 없음';$('comparison').textContent='';$('trend').textContent='';$('recent').textContent='';return}if(!selected||!fs.some(m=>m.id===selected.id))selected=fs[0];$('fixtures').innerHTML=fs.map(m=>`<button class="fixture ${m.id===selected.id?'selected':''}" data-id="${m.id}" aria-pressed="${m.id===selected.id}"><span class="muted">${m.date}</span><div class="pair">${team(m.home)}<span class="muted">vs</span>${team(m.away)}</div></button>`).join('');$('fixtures').querySelectorAll('button').forEach(b=>b.onclick=()=>{selected=fs.find(m=>m.id===b.dataset.id);renderMatches()});let m=selected,hs=games(m.home,null,m.date).slice(-5),as=games(m.away,null,m.date).slice(-5),h=calc(m.home,hs),a=calc(m.away,as);let c1=colour(m.home),c2=colour(m.away);if(c1===c2)c2=dark(T[m.away].secondary)?T[m.away].secondary:'#586779';
let stats=[['승점',h.p,a.p,0],['경기당 득점',h.n?h.gf/h.n:null,a.n?a.gf/a.n:null,1],['경기당 실점',h.n?h.ga/h.n:null,a.n?a.ga/a.n:null,1],['경기당 기대 득점',h.n?h.xg/h.n:null,a.n?a.xg/a.n:null,2]];
$('comparison').innerHTML=`<div class="matchhead"><div class="club">${badge(m.home,true)}${esc(T[m.home].name)}</div><div class="versus">VS</div><div class="club right">${esc(T[m.away].name)}${badge(m.away,true)}</div></div>${stats.map(([label,x,y,n])=>{let max=Math.max(x||0,y||0,1);return `<div class="stat"><strong>${x===null?'—':x.toFixed(n)}</strong><div><label>${label}</label><div class="bars"><div class="track left"><span class="fill" style="width:${(x||0)/max*100}%;background:${c1}"></span></div><div class="track"><span class="fill" style="width:${(y||0)/max*100}%;background:${c2};border-style:dashed"></span></div></div></div><strong>${y===null?'—':y.toFixed(n)}</strong></div>`}).join('')}<div class="matchhead"><div>${form(m.home,hs)}<span class="muted">${h.n}경기</span></div><span></span><div style="justify-self:end">${form(m.away,as)}<span class="muted">${a.n}경기</span></div></div>`;
let max=Math.max(1,...hs.map(g=>g.home===m.home?g.hx:g.ax),...as.map(g=>g.home===m.away?g.hx:g.ax));max=Math.ceil(max);function line(ms,id,c,dash){let points=ms.map((g,i)=>`${40+i*70},${145-(g.home===id?g.hx:g.ax)/max*115}`).join(' ');return `<polyline points="${points}" fill="none" stroke="${c}" stroke-width="3" ${dash?'stroke-dasharray="7 5"':''}/>`+ms.map((g,i)=>`<circle cx="${40+i*70}" cy="${145-(g.home===id?g.hx:g.ax)/max*115}" r="4" fill="${c}"><title>${esc(T[id].name)} ${g.date} xG ${(g.home===id?g.hx:g.ax).toFixed(2)}</title></circle>`).join('')}
$('trend').innerHTML=`<div class="legend"><span><i style="--c:${c1}"></i>${esc(T[m.home].name)}</span><span><i class="dash" style="--c:${c2}"></i>${esc(T[m.away].name)}</span></div><svg class="chart" viewBox="0 0 360 180" role="img" aria-label="양 팀 최근 리그 경기 기대 득점, 상세 수치는 표에 표시">${[0,max/2,max].map(v=>`<line x1="35" x2="330" y1="${145-v/max*115}" y2="${145-v/max*115}" stroke="#e0e6ee"/><text x="4" y="${150-v/max*115}" fill="#536174" font-size="11">${v.toFixed(1)}</text>`).join('')}${line(hs,m.home,c1,false)}${line(as,m.away,c2,true)}<text x="35" y="171" fill="#536174" font-size="11">이전 경기</text><text x="270" y="171" fill="#536174" font-size="11">최근 경기</text></svg><div class="muted">같은 경기 순서로 비교 · xG: 기회의 득점 기대치</div><details><summary>수치 보기</summary>${rows(m.home,hs)}${rows(m.away,as)}</details>`;$('recent').innerHTML=rows(m.home,hs)}
function renderTeam(){let ts=Object.values(T).filter(t=>t.league===L).sort((a,b)=>a.name.localeCompare(b.name));let old=$('teamselect').value;$('teamselect').innerHTML=ts.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('');if(ts.some(t=>t.id===old))$('teamselect').value=old;else $('teamselect').value=L==='EPL'?'understat:83':'understat:148';updateTeam()}
function updateTeam(){let id=$('teamselect').value,ms=games(id,$('season').value),s=calc(id,ms);$('teamcontent').innerHTML=`<div class="club">${badge(id,true)}${esc(T[id].name)}</div>${s.n?`<div class="summary"><div><strong>${s.n}</strong><label>경기</label></div><div><strong>${s.p}</strong><label>승점</label></div><div><strong>${(s.xg/s.n).toFixed(2)}</strong><label>경기당 xG</label></div><div><strong>${(s.xga/s.n).toFixed(2)}</strong><label>경기당 기대 실점</label></div></div>${form(id,ms.slice(-5))}${rows(id,ms.slice(-10))}`:'<p class="muted">선택한 시즌의 리그 자료가 없습니다.</p>'}`}
function renderLeague(){let map={};D.completed.filter(m=>m.league===L&&m.season==='2026/27').forEach(m=>[m.home,m.away].forEach(id=>{map[id]=true}));let ss=Object.keys(map).map(id=>({id,...calc(id,games(id,'2026/27'))})).sort((a,b)=>b.p-a.p||(b.gf-b.ga)-(a.gf-a.ga)||T[a.id].name.localeCompare(T[b.id].name));$('standings').innerHTML=`<table><thead><tr><th>팀</th><th>경기</th><th>승</th><th>무</th><th>패</th><th>득실</th><th>승점</th></tr></thead><tbody>${ss.map(s=>`<tr><td>${team(s.id)}</td><td>${s.n}</td><td>${s.w}</td><td>${s.d}</td><td>${s.l}</td><td>${s.gf-s.ga}</td><td><strong>${s.p}</strong></td></tr>`).join('')}</tbody></table><p class="note">경기 결과 집계 · 징계에 따른 승점 조정 미반영</p>`}
function render(){['matches','team','leagueview'].forEach(id=>$(id).hidden=id!==({matches:'matches',team:'team',league:'leagueview'}[V]));$('heading').textContent={matches:'다가오는 경기',team:'팀 분석',league:'리그 현황'}[V];document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===V));if(V==='matches')renderMatches();if(V==='team')renderTeam();if(V==='league')renderLeague()}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{V=b.dataset.view;render()});$('league').onchange=()=>{L=$('league').value;selected=null;render()};$('teamselect').onchange=updateTeam;$('season').onchange=updateTeam;$('lastdate').textContent=D.last_date;render();
</script></body></html>'''
page = page.replace('__PAYLOAD__', json.dumps(payload,ensure_ascii=False,separators=(',',':')).replace('</','<\\/'))
with (OUT/'index.html').open('x',encoding='utf-8') as f:f.write(page)
assert '사이트 디자인 기준' not in page and 'DESIGN-SYSTEM' not in page
print(json.dumps(dict(teams=len(teams),official_colour_families=len(official),completed=len(rows),scheduled=len(scheduled),last_date=payload['last_date']),ensure_ascii=False))
